import * as THREE from 'three';
export function createHeldItem(id){const group=new THREE.Group(),metal=new THREE.MeshStandardMaterial({color:0x566773,roughness:.48,metalness:.7}),grip=new THREE.MeshStandardMaterial({color:0x273d42,roughness:.9}),accent=new THREE.MeshStandardMaterial({color:id==='shockwave'?0xa183ff:0x63dce9,emissive:id==='shockwave'?0x493278:0x154852,emissiveIntensity:.7});const box=(s,p,m)=>{const mesh=new THREE.Mesh(new THREE.BoxGeometry(...s),m);mesh.position.set(...p);group.add(mesh);return mesh;};if(id==='pickaxe'){box([.045,.75,.05],[0,.08,0],grip);box([.5,.095,.13],[0,.46,0],metal);box([.15,.13,.16],[-.23,.42,0],metal).rotation.z=-.4;box([.18,.035,.135],[.18,.48,0],accent);}else if(id==='shockwave'){const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(.13,1),metal);group.add(mesh);for(const axis of [0,1]){const ring=new THREE.Mesh(new THREE.TorusGeometry(.135,.016,6,16),accent);ring.rotation.x=axis*Math.PI/2;group.add(ring);}}else{box(id==='shield'?[.14,.26,.14]:[.3,.18,.16],[0,.08,0],id==='shield'?accent:grip);box([.09,.04,.15],[0,.08,.01],metal);if(id==='health'){box([.18,.045,.012],[0,.08,.09],accent);box([.045,.12,.012],[0,.08,.09],accent);}}return group;}
